Item.method_code:
const item = window.getItem();
const currentPermissionId = aras.getItemProperty(item, 'permission_id');
const resultOptions = { hidden: true };

if (!currentPermissionId) {
	return resultOptions;
}

const additionalData = target.additional_data || (target.additional_data = {});

Object.assign(resultOptions, {
	checked: currentPermissionId === additionalData.permissionId,
	disabled: !window.isEditMode
});

if (additionalData.isDefault) {
	const defaultSuffix = aras.getResource(
		'',
		'tearoffmenu.default_permission_sfx'
	);

	if (!target.label.endsWith(defaultSuffix)) {
		resultOptions.label = target.label + defaultSuffix;
	}
}

return resultOptions;
